import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import { withServerSsh, exec, SETUP_TIMEOUT_MS, INSTALL_TIMEOUT_MS } from "../lib/ssh-exec";
import {
  controlSpec,
  isGameFamily,
  isPowerAction,
  remoteLocateDir,
  runRcon,
  parsePlayers,
  computeNextRun,
  computeNextIntervalRun,
  shq,
  buildWorldBackupScript,
  isSafeRemotePath,
  GAME_BACKUP_DIR,
  readGameLogs,
  logTrackingSpec,
  type GameControlSpec,
} from "../lib/game-control";
import { checkGamePortOpen, gamePortForServer, gamePortBoundInGuest, retryCheck } from "./provision-health";
import { gameCheckTarget, intentForPowerAction, type IntentSource } from "../lib/game-runtime";
import { recordIntent, refreshRuntime } from "../lib/game-runtime-probe";
import { buildGameSetupScript, dockerContainerNameFrom, dockerHostMountsFrom } from "./game-variant";
import { mcJarPinForSetup } from "./mcjar-pin";
import { readFivemPlayers } from "./fivem";
import type { Job } from "@prisma/client";

/**
 * How long GAME_POWER's post-action port check waits for the game process to
 * bind its port before giving up (`GameControlSpec.powerStartTimeoutMs` can
 * override this per family). Deliberately much shorter than provisioning's
 * GAME_PORT_CHECK_TIMEOUT_MS (300s) — this runs synchronously from a customer
 * pressing Start/Restart in the dashboard, not an unattended provision, and
 * most families that are going to come up at all do so in a few seconds once
 * systemd reports the unit active.
 *
 * CORRECTION (2026-09-30): this comment used to claim a slow family "only
 * delays the SUCCESS notification, never falsely reports failure early" — that
 * was wrong. On timeout this DOES throw, which fails the job and tells the
 * customer the start failed, even when the process goes on to come up fine a
 * moment later (real incident: a Terraria customer's start kept "failing"
 * while the server was actually booting normally — world load + "Settling
 * liquids" legitimately took longer than 30s). Any family whose real boot can
 * exceed this window needs `powerStartTimeoutMs` set on its `GameControlSpec`,
 * not just an assumption that 30s is always enough.
 */
const GAME_POWER_PORT_CHECK_TIMEOUT_MS = 30_000;
const GAME_POWER_PORT_CHECK_INTERVAL_MS = 3_000;

/**
 * Game server control-panel worker handlers.
 *
 * Registered in worker/index.ts:
 *   GAME_POWER:     gamePower,
 *   GAME_BACKUP:    gameBackup,
 *   GAME_REINSTALL: gameReinstall,
 * and `gameScheduleSweep()`, `playerTrackingSweep()` (RCON families) and
 * `logPlayerTrackingSweep()` (log-only families, e.g. Valheim) called on ~60s
 * timers.
 *
 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
 * and the root password is never surfaced in an error (only a trimmed remote stderr
 * is, which never contains it).
 *
 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
 */

const CONTROL_FIELDS = {
  id: true,
  userId: true,
  hostname: true,
  status: true,
  rootPassword: true,
  rootPasswordEnc: true, sshManagementKeyEnc: true,
  sshPort: true,
  dedicatedIp: { select: { address: true } },
  node: { select: { publicIp: true } },
  osTemplate: { select: { family: true } },
  gamePlan: { select: { gameFamily: true } },
  portForwards: { select: { publicPort: true, guestPort: true, protocol: true } },
} as const;

export type ControlServer = {
  id: string;
  userId: string;
  hostname: string;
  status: string;
  rootPassword: string | null;
  rootPasswordEnc: string | null;
  sshManagementKeyEnc?: string | null;
  sshPort: number | null;
  dedicatedIp: { address: string } | null;
  node: { publicIp: string } | null;
  osTemplate: { family: string | null };
  gamePlan: { gameFamily: string | null } | null;
  portForwards?: { publicPort: number; guestPort: number; protocol: string }[];
};

/**
 * Make the CURRENT attempt of this job its last one.
 *
 * `runJob` (worker/index.ts) retries any thrown job up to MAX_ATTEMPTS. For
 * GAME_POWER that is actively harmful once the systemctl action itself has
 * run: a "restart" that timed out on its port check was re-run twice more —
 * three restarts, three "could not restart" notifications, for a server that
 * was (in most real cases) already back up. Setting attempts to a value no
 * retry ladder accepts makes the coming throw terminal. Best-effort.
 */
export async function noRetry(jobId: string): Promise<void> {
  await db.job.update({ where: { id: jobId }, data: { attempts: 99 } }).catch(() => {});
}

/**
 * Wait for the game to really listen after a start/restart, checking the path
 * a PLAYER uses — see lib/game-runtime.ts's gameCheckTarget for the bug this
 * replaced (probing node.publicIp:<guest port>, which no node forwards).
 * With no public path for the check port, the in-guest binding is the whole
 * check (and is said to be).
 */
export async function waitForGamePort(
  server: ControlServer,
  timeoutMs: number,
  intervalMs: number
): Promise<{ ok: boolean; error?: string; target: string | null } | null> {
  const game = gamePortForServer(server);
  if (!game) return null;
  const verifyBound = () => gamePortBoundInGuest(server as SftpServer, game.port, game.protocol);
  const target = gameCheckTarget(server, game, process.env.PUBLIC_IP ?? null);
  if (target) {
    const r = await checkGamePortOpen(target.host, target.port, game.protocol, { timeoutMs, intervalMs, verifyBound });
    return { ok: r.ok, error: r.ok ? undefined : r.error, target: `${target.host}:${target.port}` };
  }
  const r = await retryCheck(
    async () => {
      const bound = await verifyBound();
      return bound === true ? { ok: true } : { ok: false, error: bound === false ? "nothing bound in the guest yet" : "guest could not be asked" };

      return bound === true ? { ok: true } : { ok: false, error: bound === false ? "nothing bound in the guest yet" : "guest could not be asked" };
    },
    { timeoutMs, intervalMs }
  );
  return { ok: r.ok, error: r.ok ? undefined : r.error, target: null };
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-control] notify failed", e);
  }
}

function resolveSpec(server: ControlServer): GameControlSpec {
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (!isGameFamily(fam)) throw new Error("not a game server");
  const spec = controlSpec(fam);
  if (!spec) throw new Error("no control spec for family");
  return spec;
  if (/NXGP:UNIT:NONE/.test(text)) {
    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
    throw new Error("game power: no service unit found");
  }
  const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
  const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
  if (!/NXGP:END/.test(text) || rc !== 0) {
    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
    await refreshRuntime(server.id).catch(() => null);
    await noRetry(job.id);
    throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
  }

  // FOUND LIVE 2026-09-20: this used to notify success on rc===0 + an END
  // marker alone, without ever checking `state` — so a unit that restarted
  // straight into "failed" (or stayed "activating"/crash-looping) was still
  // reported to the customer as "restarted (now failed)", i.e. success. A
  // `Restart=always` unit around a crash-looping container (exactly what a
  // wrong-Java-version Minecraft image produces — see
  // lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS) reports "active" between
  // crashes just as readily as a genuinely healthy server, so `systemctl`
  // alone was never going to be enough either way.
  if (action !== "stop" && state !== "active") {
    await notify(
      server.userId,
      `Could not ${action} the ${spec.label} service`,
      `${spec.label} on ${server.hostname} is "${state}" after the ${action}, not active. ` +
        `Diagnose with: systemctl status <unit> ; journalctl -u <unit> -n 50`,
      href
    );
    await refreshRuntime(server.id).catch(() => null);
    await noRetry(job.id);
    throw new Error(`game power: ${action} left service in state=${state}`);
  }

  // Real port-bound check — the same in-guest positive-confirmation path
  // PROVISION uses (worker/provision-health.ts's checkGamePortOpen +
  // gamePortBoundInGuest), reused here for the other place this class of bug
  // hid: a systemd unit reporting "active" proves the OBJECT exists, never
  // that the game process inside actually bound its port. Best-effort and
  // deliberately short (GAME_POWER_PORT_CHECK_TIMEOUT_MS) — families with no
  // GAME_PORT entry, or a NAT server whose game port isn't forwarded, skip
  // this silently rather than block or falsely fail on a check that can't
  // mean anything for them.
  if (action !== "stop" && state === "active") {
    const portCheck = await waitForGamePort(
      server,
      spec.powerStartTimeoutMs ?? GAME_POWER_PORT_CHECK_TIMEOUT_MS,
      GAME_POWER_PORT_CHECK_INTERVAL_MS
    );
    if (portCheck && !portCheck.ok) {
      const game = gamePortForServer(server)!;
      // Cache what the guest really looks like now, so the dashboard shows
      // "Starting"/"Not responding" instead of a guess.
      await refreshRuntime(server.id).catch(() => null);
      await notify(
        server.userId,
        `${spec.label} service ${action}ed, but the game isn't answering yet`,
        `The ${spec.label} service on ${server.hostname} is running, but nothing answered on ` +
          `${portCheck.target ?? `${game.port}/${game.protocol} inside the server`} within ` +
          `${Math.round((spec.powerStartTimeoutMs ?? GAME_POWER_PORT_CHECK_TIMEOUT_MS) / 1000)}s ` +
          `(${portCheck.error ?? "no further detail"}). It may still be loading — the status badge on your ` +
          `dashboard shows the live state. If it stays "Not responding", check Console → Logs.`,
        href
      );
      // Terminal: re-running a restart that already happened only restarts the game again.
      await noRetry(job.id);
      throw new Error(
        `game power: ${action} reported active but port ${game.port}/${game.protocol} never answered` +
          `${portCheck.target ? ` on ${portCheck.target}` : " in the guest"}: ${portCheck.error ?? ""}`
      );
    }
  }

  await notify(
    server.userId,
    `${spec.label} service ${action}ed on ${server.hostname}`,
    action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
    href
  );

  // Persist the real systemd state so the dashboard's status dot can reflect
  // it. GAME_POWER only ever touches the game SERVICE inside the VM, never
  // `Server.status` (the VM's own power state) — those are genuinely
  // different things, but the panel's "Online/Offline" label was reading
  // `Server.status` alone, so a customer who stopped just their game service
  // (VM still up) kept seeing "Online" no matter what they did. Found live
  // 2026-09-09 via a real customer confused why "Status: Online" never
  // changed after repeated stop/start attempts. `_serviceState` follows the
  // same gameConfig-internal-marker convention as `_real`/`_realOk`/
  // `_appliedAt` elsewhere in this file's siblings — no schema migration
  // needed for what's fundamentally transient, best-effort runtime state.
  try {
    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
    const gameConfig = { ...(fresh?.gameConfig as Record<string, unknown> | null ?? {}), _serviceState: state };
    await db.server.update({ where: { id: server.id }, data: { gameConfig } });
  } catch (e) {
    console.error(`[game-control] could not persist _serviceState for ${server.hostname}`, e);
  }
  // And the real runtime cache (badge + controls), from a fresh probe.
  await refreshRuntime(server.id).catch(() => null);
}

/**
 * Archive the world/save dir into GAME_BACKUP_DIR as a timestamped .tar.gz.
 * Shared by GAME_BACKUP and the pre-update safety backup (worker/game-update.ts).
 */
export async function createWorldBackup(
  server: SftpServer,
  spec: GameControlSpec,
  tag = ""
): Promise<{ ok: true; archive: string; size: number } | { ok: false; msg: string }> {
  return withServerSsh(server, async (conn) => {
    const dir = await remoteLocateDir(conn, spec.dataRoots);
    if (!dir || !isSafeRemotePath(dir)) return { ok: false as const, msg: "Could not locate the world/save directory." };
    // Timestamped archive under the fixed backup dir. `parent`/`base` are derived
    // from the located (allowlisted) dir; every value interpolated is single-quoted.
    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
    const safeTag = /^[a-z0-9-]{0,24}$/.test(tag) && tag ? `-${tag}` : "";
    const archive = `${GAME_BACKUP_DIR}/${spec.family}-${ts}${safeTag}.tar.gz`;
    const script = buildWorldBackupScript(dir, archive, spec.family === "valheim");
