type RconConfig = FileRconConfig | DockerEnvRconConfig;

export type GameControlSpec = {
  family: GameFamily;
  label: string;
  /** systemd unit-name hints (first that resolves wins). Compile-time constants. */
  serviceHints: string[];
  /** Directory candidates that hold the world/save data (for listing + backup). */
  dataRoots: string[];
  /** Remote console protocol. */
  rcon: RconProtocol;
  /** Where/how to read RCON creds (present only when rcon === "source"). */
  rconConfig?: RconConfig;
  /** RCON verb that lists connected players (present when supported). */
  listCommand?: string;
  /** RCON verb template for kicking a player (`%s` = validated name/id). */
  kickCommand?: string;
  /** RCON verb template for banning a player (`%s` = validated name/id). */
  banCommand?: string;
  /**
   * Override for GAME_POWER's post-start port-bind check (worker/game-control.ts's
   * GAME_POWER_PORT_CHECK_TIMEOUT_MS, 30s default). Most families' game process
   * binds its port within a few seconds of systemd reporting the unit active, so
   * 30s is deliberately short — but a family whose own boot legitimately takes
   * longer (world loading, not just process startup) needs real headroom here,
   * or a perfectly healthy start gets reported as a failure. Undefined = use the
   * 30s default.
   */
  powerStartTimeoutMs?: number;
};

/**
 * The control facts per game family.
 *
 * RCON reality (why not every "has RCON" game gets a wire here):
 *  - minecraft: native Source RCON (enable-rcon / rcon.password / rcon.port), read from a config file.
 *  - cs2:       native Source RCON (rcon_password; port defaults to the game port), read from a config file.
 *  - palworld:  native RCON, Source-protocol framing (RCONEnabled/RCONPort/AdminPassword), read from a config file.
 *  - ark, arkasa, tf2, l4d2, projectzomboid: native Source RCON, each verified
 *    2026-09-24 against the platform's real docker image/entrypoint (see each

 * How long GAME_REINSTALL's post-action port check waits before giving up.
 * Longer than GAME_POWER's (a fresh `docker create` can need to pull an image,
 * not just restart an already-cached container) but still far short of
 * provisioning's own 300s — a wipe+reinstall that's still not up after a
 * minute gets a "check back shortly" notification rather than a hard failure
 * (the SSH script itself already confirmed the systemd unit is active; this
 * is only extra confirmation the game process itself bound its port).
 */
const GAME_REINSTALL_PORT_CHECK_TIMEOUT_MS = 60_000;
const GAME_REINSTALL_PORT_CHECK_INTERVAL_MS = 4_000;

/**
 * GAME_REINSTALL — Danger Zone "Wipe & reinstall this game". Re-provisions the
 * GAME ONLY against the SAME, already-existing VM:
 *
 *   1. stop the game's systemd unit and `docker rm -f` its container
    `echo "NXREINSTALL:SETUP_RC:$?"`,
    `sleep 3`,
    unitName
      ? `st=$(systemctl is-active ${shq(unitName)} 2>/dev/null); echo "NXREINSTALL:STATE:${"$"}{st:-unknown}"`
      : `echo "NXREINSTALL:STATE:unknown"`,
  ].join("\n");

  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, script, INSTALL_TIMEOUT_MS));
  const text = out.stdout;
  if (!/NXREINSTALL:WIPED/.test(text)) {
    await notify(server.userId, `Reinstall failed on ${server.hostname}`, "Could not stop/remove the existing game service before reinstalling — nothing was wiped.", href);
    throw new Error("game reinstall: wipe step did not run");
  }
  const setupRc = Number(/NXREINSTALL:SETUP_RC:(-?\d+)/.exec(text)?.[1] ?? "1");
  const state = /NXREINSTALL:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
  if (setupRc !== 0 || state !== "active") {
    await notify(
      server.userId,
      `${spec.label} reinstall did not come back up on ${server.hostname}`,
      `The old install was wiped, but the fresh one is "${state}" after setup (exit ${setupRc}). ` +
        `Check Console → Logs, or contact support — the old data has already been removed and cannot be recovered from this server.`,
      href
    );
    throw new Error(`game reinstall: setup rc=${setupRc} state=${state}`);
  }

  // Real port-bound confirmation — same discipline as gamePower/provisioning
  // (a systemd unit reporting "active" only proves the object exists, never
  // that the game process inside actually bound its port).
  // Same public-path target as GAME_POWER (lib/game-runtime.ts gameCheckTarget) —
  // this used to probe node.publicIp:<guest port>, which no node forwards.
  const game = gamePortForServer(server);
  if (game) {
    const portCheck = (await waitForGamePort(server, GAME_REINSTALL_PORT_CHECK_TIMEOUT_MS, GAME_REINSTALL_PORT_CHECK_INTERVAL_MS))!;
    await refreshRuntime(server.id).catch(() => null);
    if (!portCheck.ok) {
      await notify(
        server.userId,
        `${spec.label} reinstalled — still starting up on ${server.hostname}`,
        `The service is active, but nothing is answering on ${game.port}/${game.protocol} yet. A freshly pulled image's ` +
          `first boot can take a few minutes — check back shortly, or watch Console → Logs.`,
        href
      );
      // Not a hard failure: the wipe+setup both genuinely succeeded, this is
      // only the short best-effort confirmation window running out early.
      return;
    }
  }

  await notify(
    server.userId,
    `${spec.label} reinstalled on ${server.hostname}`,
    "The game was wiped and freshly reinstalled on this server. Your VPS itself was not touched or recreated.",
    href
  );
}

/**
 * Fire due scheduled tasks. Selects enabled GameSchedule rows whose `nextRunAt`
 * has passed. For kind="restart", enqueues a GAME_POWER restart; for kind="command",
 * sends an RCON command directly. Advances `nextRunAt` appropriately (daily or
 * interval-based). Idempotent / safe on a timer.
 */
export async function gameScheduleSweep(): Promise<void> {
  const now = new Date();
  const due = await db.gameSchedule.findMany({
    where: { enabled: true, nextRunAt: { lte: now } },
    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } }, gameRuntime: { select: { intent: true } } } } },
    take: 100,
  });
  if (due.length === 0) return;

  for (const s of due) {
    // Always advance the clock first so a server that is down / mid-operation does
    // not cause the same row to be reselected every tick.
    const nextRunAt = s.intervalMinutes
      ? computeNextIntervalRun(s.intervalMinutes, now)
      : computeNextRun(s.hour, s.minute, now);
    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});

    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
    if (!isGameFamily(fam)) continue;
    if (s.server.status !== "RUNNING") continue;
    // A scheduled restart must not resurrect a game its owner deliberately
    // stopped — "restart" of an inactive unit is a start. Skipped, not queued.
    if (s.server.gameRuntime?.intent === "stopped") continue;

    if (s.kind === "command" && s.command) {
      // Send RCON command directly (e.g. save-all, weather clear).
      const spec = controlSpec(fam);
      if (!spec || spec.rcon === "none") continue;
      // Load full server for SSH access.
      const server = await db.server.findUnique({ where: { id: s.server.id }, select: CONTROL_FIELDS });
      if (!server) continue;
      try {
        await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
      } catch {
        // Best-effort: command schedules silently skip on failure.
      }
    } else {
      // Restart schedule: check for busy jobs first.
  const unit = safeUnitName(after?.probe.unit ?? before?.probe.unit);
  const runNotes: string[] = [];
  let recoverFailed: string | null = null;
  if (plan.action !== "none" && unit && !SANDBOX) {
    const verb = plan.action === "restore-stop" ? "stop" : plan.action === "restart" ? "restart" : "start";
    try {
      const r = await withServerSsh(server as unknown as SftpServer, (conn) =>
        sshExec(conn, `systemctl ${verb} '${unit}' >/dev/null 2>&1; echo "NXCR:$?:$(systemctl is-active '${unit}' 2>/dev/null)"`, SETUP_TIMEOUT_MS)
      );
      const m = /NXCR:(\d+):(\w*)/.exec(r.stdout);
      const ok = !!m && m[1] === "0" && (verb === "stop" ? m[2] !== "active" : m[2] === "active");
      if (ok && verb !== "stop") {
        const port = await waitForGamePort(server as unknown as ControlServer, controlSpec(family)?.powerStartTimeoutMs ?? 60_000, 4_000);
        if (port && !port.ok) {
          runNotes.push(`${plan.note} The service is running, but the game wasn't answering yet when we checked — it may still be loading.`);
        } else runNotes.push(plan.note);
      } else if (ok) runNotes.push(plan.note);
      else {
        const msg = `Tried to ${verb} the server after applying settings, but it is "${m?.[2] || "unknown"}".`;
        runNotes.push(msg);
        if (plan.action === "recover-start") recoverFailed = msg;
      }
    } catch (e) {
      const msg = `Could not ${verb} the server after applying settings: ${String((e as Error)?.message ?? e).slice(0, 160)}`;
      runNotes.push(msg);
      if (plan.action === "recover-start") recoverFailed = msg;
    }
  } else if (plan.note) {
    runNotes.push(plan.action === "none" || unit ? plan.note : `${plan.note} (We couldn't find the game service to act on — use the power controls.)`);
  }

