/**
 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
 * the family's control spec (compile-time constants); `action` is one of the three
 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
 * a successful action (the same discipline as worker/game-update.ts).
 */
function powerScript(spec: GameControlSpec, action: string): string {
  const hints = spec.serviceHints.map(shq).join(" ");
  return [
    `unit=""`,
    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
    `echo "NXGP:UNIT:$unit"`,
    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
    `echo "NXGP:END"`,
  ].join("\n");
}

/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
export async function gamePower(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game power: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);

  const p = (job.payload ?? {}) as { action?: string; announce?: boolean; source?: IntentSource; by?: string | null };
  const action = String(p.action ?? "");
  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  // Record what was ASKED for before doing it, whatever the outcome — this is
  // what lets the dashboard and the fleet sweep tell "stopped by choice" from
  // "crashed". Only the first attempt of a job records (a retry is not a new ask).
  const intent = intentForPowerAction(action);
  if (intent && job.attempts <= 1) await recordIntent(server.id, intent, p.source ?? "customer", p.by ?? null);

  if (SANDBOX) {
    await notify(
      server.userId,
      `Game service ${action} (sandbox) on ${server.hostname}`,
      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
      href
    );
    return;
  }
  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");

  // Optional pre-restart announce over RCON (best-effort; never fails the action).
  if (action === "restart" && p.announce && spec.rcon === "source") {
    try {
      await withServerSsh(server as SftpServer, (conn) =>
        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
      );
    } catch (e) {
      console.error("[game-control] restart announce failed (continuing)", e);
    }
  }

  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
  const text = out.stdout;
  if (/NXGP:UNIT:NONE/.test(text)) {

    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
    socket.once("connect", () => {
      if (!opts.expectSshBanner) finish({ ok: true });
      // else: wait for the banner line on "data" below.
    });
    if (opts.expectSshBanner) {
      socket.on("data", (chunk) => {
        buf += chunk.toString("utf8");
        if (buf.includes("\n") || buf.length >= 256) {
          const line = buf.trim();
          if (line.startsWith("SSH-")) finish({ ok: true, detail: line.slice(0, 120) });
          else finish({ ok: false, error: `connected but no SSH banner (got: ${line.slice(0, 80) || "<empty>"})` });
        }
      });
    }
    socket.connect(port, host);
  });
}

/**
 * One UDP reachability probe. UDP has no handshake, so this cannot PROVE a
 * listener exists the way a TCP connect can — but on Linux, a datagram sent
 * to a UDP port nothing is bound to draws a prompt ICMP port-unreachable,
 * which node surfaces as an `ECONNREFUSED` error on a *connected* UDP socket.
 * No error within the window is treated as reachable. This is the same class
 * of "did the process actually bind the port" evidence the TCP check gives —
 * it would have caught the Terraria-style bug (container up, nothing bound)
 * on a UDP-only game exactly the same way.
 */
function udpAttempt(host: string, port: number, opts: { timeoutMs: number }): Promise<{ ok: true } | { ok: false; error: string }> {
  return new Promise((resolve) => {
    const socket = dgram.createSocket("udp4");
    let settled = false;
    const finish = (result: { ok: true } | { ok: false; error: string }) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.removeAllListeners();
      socket.close();
      resolve(result);
    };
    const timer = setTimeout(() => finish({ ok: true }), opts.timeoutMs);
    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
    socket.connect(port, host, () => {
      socket.send(Buffer.from([0]), (err) => {
        if (err) finish({ ok: false, error: (err as NodeJS.ErrnoException).code ?? err.message });
      });
    });
  });
}

// ---------------------------------------------------------------------------
// Public checks used by worker/index.ts's provision().
// ---------------------------------------------------------------------------

/**
 * Retries every ~5s for up to 2 minutes. SSH normally comes up within
 * seconds of the guest booting — cloud-init's user/ssh-key modules run near
 * the START of boot, well before the game/app install `runcmd` — and by the
 * time provision() reaches this check it has usually already waited up to
 * 180s for the guest agent, so sshd has almost always had time. Two minutes
 * of its own headroom on top covers the case where the agent never answers
 * (not every image ships qemu-guest-agent) but sshd is merely slow.
 */
export const SSH_CHECK_TIMEOUT_MS = 120_000;
export const SSH_CHECK_INTERVAL_MS = 5_000;

/**
 * Real TCP connect + SSH banner check against the server's actual reachable
 * address (caller passes the dedicated IP, or the NAT host + assigned SSH
 * port — see worker/index.ts's `dedicated`/`sshPort` computation, reused
 * here rather than recomputed).
 */
export async function checkSshReachable(
  host: string,
  port: number,
  opts?: { timeoutMs?: number; intervalMs?: number; sleep?: (ms: number) => Promise<void> }
): Promise<RetryResult> {
  return retryCheck(() => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: true }), {
    timeoutMs: opts?.timeoutMs ?? SSH_CHECK_TIMEOUT_MS,
    intervalMs: opts?.intervalMs ?? SSH_CHECK_INTERVAL_MS,
    sleep: opts?.sleep,
  });
}

/**
 * Retries every 10s for up to 5 minutes (30 attempts). A game server takes
 * meaningfully longer than SSH to actually start listening — the setup
 * script still has to run AFTER boot (docker install if not cached, image
 * pull, first-run world/save generation) once cloud-init's `runcmd` fires.
 * 5 minutes is a principled default sized for a cold Docker image pull on
 * this host, not an empirically measured figure (no real order was placed
 * to time one for this change) — the timeout/interval are named exports so
 * they can be retuned in one place once real timings are observed.
 */
export const GAME_PORT_CHECK_TIMEOUT_MS = 300_000;
  const attempt: CheckOnce =
    protocol === "tcp"
      ? () => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: false })
      : () => udpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS });
  const verify = opts?.verifyBound;
  const checkOnce: CheckOnce = verify
    ? async () => {
        const r = await attempt();
        if (!r.ok) return r;
        const bound = await verify();
        if (boundVerdictPasses(protocol, bound)) return r;
        return {
          ok: false,
          error:
            bound === false
              ? `the ${port}/${protocol} probe drew no refusal, but nothing inside the guest is bound to ` +
                `${port}/${protocol} — silence is not the game listening`
              : `the ${port}/udp probe drew no refusal, but the guest could not confirm anything is bound ` +
                `to ${port}/udp — for UDP that is no evidence at all, not a pass`,
        };
      }
    : attempt;
  return retryCheck(checkOnce, {
    timeoutMs: opts?.timeoutMs ?? GAME_PORT_CHECK_TIMEOUT_MS,
    intervalMs: opts?.intervalMs ?? GAME_PORT_CHECK_INTERVAL_MS,
    sleep: opts?.sleep,
    shouldAbort: opts?.shouldAbort,
  });
}

/**
 * Is a socket bound to `port` present in a `/proc/net/{udp,udp6,tcp,tcp6}`
 * table? Pure parser over the raw table text so it is unit-testable; the
 * caller concatenates the guest's own tables plus each running container's
 * (`/proc/<pid>/net/...`), because a containerised game binds the port in its
 * OWN network namespace, not the guest's.
 *
 * WHY THIS EXISTS: `udpAttempt` resolves SUCCESS on timeout — for a
 * connectionless protocol there is nothing else a generic prober can do, since
 * a healthy game server has no obligation to answer a byte of nonsense. So the
 * UDP game-port check passed on silence, and silence is exactly what a guest
 * emits while a crash-looping container is between restarts (the packet is
 * dropped rather than refused). Caught live 2026-09-07: a The Forest order was
 * marked DONE and handed over as ready while its container had restarted 118
 * times, had never started the game at all ("Missing SERVER_STEAM_ACCOUNT_TOKEN
 * … Aborting server start"), and had nothing bound to any port. That is the
 * valheim: verified against the `lloesche/valheim-server` Docker image (the
 * platform's real Valheim template) 2026-09-20 — a join logs
 * `Got character ZDOID from <name> : <id>`, and the server's own connection
 * bookkeeping logs `... now N player(s)` on every disconnect. The join line
 * names the joiner; the disconnect line does NOT name the leaver, only the new
 * total — see worker/game-control.ts's `logPlayerTrackingSweep` doc comment
 * for exactly how that gap is handled (inference, not observation, and always
 * labeled as such).
 */
export const GAME_LOG_TRACKING: Partial<Record<GameFamily, LogTrackingSpec>> = {
  valheim: {
    joinRe: /Got character ZDOID from (.+?) : /,
    countRe: /now (\d+) player\(s\)/i,
  },
  // rust: vanilla Rust's output log names the player on BOTH ends, as
  //   <ip>:<port>/<steamid64>/<name> joined [<os>/<steamid64>]
  //   <ip>:<port>/<steamid64>/<name> disconnecting: <reason>
  // Format taken from Facepunch's documented server output and community log
  // parsers; NOT yet verified against a live Nxeon Rust server (the sweep only
  // ever stores the captured name, never the ip or steam id).
  rust: {
    joinRe: /\d{1,3}(?:\.\d{1,3}){3}:\d+\/\d{17}\/(.+?) joined \[/,
    leaveRe: /\d{1,3}(?:\.\d{1,3}){3}:\d+\/\d{17}\/(.+?) disconnecting: /,
  },
};

export function logTrackingSpec(family: string | null | undefined): LogTrackingSpec | null {
  if (!family) return null;
  return (GAME_LOG_TRACKING as Record<string, LogTrackingSpec>)[family] ?? null;
}

/** Next UTC occurrence of hour:minute strictly after `from` (schedule planning). */
export function computeNextRun(hour: number, minute: number, from: Date = new Date()): Date {
  const next = new Date(
    Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), from.getUTCDate(), hour, minute, 0, 0)
  );
  if (next.getTime() <= from.getTime()) next.setUTCDate(next.getUTCDate() + 1);
  return next;
}

