/** States in which the game process is (believed to be) up. */
export const GAME_UP_STATES: ReadonlySet<GameRuntimeState> = new Set(["online", "unverified", "starting", "not_responding"]);

/**
 * States the fleet sweep treats as "the VM is up but the game is down" — only
 * meaningful when nobody asked for it (`stopped` is deliberately absent).
 */
export const GAME_DOWN_STATES: ReadonlySet<GameRuntimeState> = new Set(["game_stopped", "crashed", "not_responding"]);

/**
 * How long after the game (container/unit) started we still call an unbound
 * port "starting" rather than "not responding". The 2026-09-06 catalog sweep
 * measured first boots up to ~450s (Terraria/Valheim) and GAME_POWER allows
 * 180s for Minecraft/Valheim/Terraria; a warm restart is far faster. 6 minutes
 * is a deliberate middle: long enough not to cry wolf on a normal boot.
 */
export const START_GRACE_MS = 6 * 60_000;

/** A probe older than this is shown as "as of N min ago" and refreshed. */
export const RUNTIME_REFRESH_TTL_MS = 60_000;
/** A probe older than this is not trusted to drive the badge at all. */
export const RUNTIME_STALE_MS = 15 * 60_000;

export type RunIntent = "running" | "stopped";
export type IntentSource = "customer" | "admin" | "schedule" | "auto-restart" | "config" | "update" | "provision";

export function intentForPowerAction(action: string): RunIntent | null {
  if (action === "stop") return "stopped";
  if (action === "start" || action === "restart") return "running";
  return null;
}

