/** Unit-name hint / family tokens that may reach the probe script. */
const TOKEN_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;

/**
 * The read-only in-guest probe. One SSH exec, a handful of `systemctl` /
 * `docker inspect` reads and two /proc tables — cheap enough to run for the
 * whole fleet every couple of minutes, and changes nothing on the guest.
 *
 * Shape follows the platform's own conventions:
 *  - the unit is resolved from the family's controlSpec hints exactly like
 *    GAME_POWER resolves it (so the probe and the buttons always agree);
 *  - the container name is read off the unit itself (`ExecStart=docker start
 *    -a <name>`, the shape wrapDockerGameService installs) — never guessed;
 *  - the port table is read from the CONTAINER's own namespace, never the
  /** procNetHasPort over probe.netTable, done by the I/O caller (null = could not tell) */
  portBound: boolean | null;
  /** TCP connect through the public path (null = not checked, e.g. UDP) */
  externalOk: boolean | null;
  intent: RunIntent | null;
  now: Date;
  startGraceMs?: number;
};

/** Turn one probe into one state. Pure; see the module header for the rules. */
export function classifyRuntime(input: ClassifyInput): GameRuntimeState {
  const { probe: p, portBound, externalOk, intent, now } = input;
  const grace = input.startGraceMs ?? START_GRACE_MS;
  if (!p.ok) return "unknown";
  if (!p.unit && !p.container) return "unknown";

  const ctr = p.containerState;
  // No unit (a server older than wrapDockerGameService): the container's own
  // state is the service state.
  const svc = p.service ?? (p.unit ? "unknown" : ctr === "running" ? "active" : ctr ? "inactive" : "unknown");

  if (svc === "failed" || ctr === "restarting" || ctr === "dead") return "crashed";
  if (svc === "activating" || svc === "reloading") return "starting";
  if (svc === "inactive" || svc === "deactivating" || (svc !== "active" && ctr && ctr !== "running")) {
    return intent === "stopped" ? "stopped" : "game_stopped";
  }
  if (svc !== "active") return "unknown";

  // Unit active. A docker-wrapped unit can be "active" a moment before the
  // container is — or between crashes of a Restart=always loop.
  const inGrace = p.startedAt ? now.getTime() - p.startedAt.getTime() < grace : false;
  if (p.container && ctr !== "running") return inGrace ? "starting" : "crashed";
  if (p.containerHealth === "unhealthy") return "not_responding";

  if (portBound === true) return externalOk === false ? "not_responding" : "online";
  if (portBound === false) return inGrace ? "starting" : "not_responding";
  // Port table unreadable. A HEALTHCHECK that says healthy is real evidence.
  if (p.containerHealth === "healthy") return externalOk === false ? "not_responding" : "online";
  if (externalOk === true) return "online";
  return "unverified";
}

