function view(kind: PowerKind, j: PowerJobRow, action: PowerAction, now: number): PowerJobView {
  const terminal = TERMINAL.has(j.status);
  return {
    id: j.id,
    action,
    status: j.status as PowerJobStatus,
    attempts: j.attempts,
    ageMs: Math.max(0, now - j.createdAt.getTime()),
    finishedAgoMs: terminal ? Math.max(0, now - j.updatedAt.getTime()) : null,
    failure: j.status === "FAILED" ? powerFailureMessage(kind, action, j.error) : null,
  };
}

/**
 * Build the snapshot from the jobs the page already loaded (newest first — the
 * dashboard's `server.jobs` is `orderBy createdAt desc`). One in-flight job per
 * server is enforced server-side, so "the" in-flight job is unambiguous.
 */
export function powerSnapshot(kind: PowerKind, jobs: PowerJobRow[], now: Date = new Date()): PowerSnapshot {
  const t = now.getTime();
  let inflight: PowerJobView | null = null;
  let blockedBy: string | null = null;
  const finished: PowerJobView[] = [];
  for (const j of jobs) {
    const action = powerActionOf(kind, j);
    if (IN_FLIGHT.has(j.status)) {
      if (action && !inflight) inflight = view(kind, j, action, t);
      else if (!action && !blockedBy) blockedBy = BLOCKING_LABEL[j.type] ?? "Another operation";
    } else if (action && TERMINAL.has(j.status)) {
      finished.push(view(kind, j, action, t));
    }
  }
  // By finish time, not creation time: "how did the last action end" means the
  // one that ended last.
  finished.sort((a, b) => (a.finishedAgoMs ?? 0) - (b.finishedAgoMs ?? 0));
  const recent = finished.slice(0, 5);
  return { inflight, last: recent[0] ?? null, recent, blockedBy };
}
