/**
 * What a GAME_POWER start/restart should conclude when the game port is not
 * answering yet — pure decision logic plus an orchestrator with injected I/O,
 * so it is testable without SSH or a database.
 *
 * FOUND LIVE 2026-10-02 (Valheim "terraheim", node-3): restart jobs were marked
 * FAILED ("port 2456/udp never answered ... ECONNREFUSED") although the game
 * came up normally ~65-75s after `docker start` (steamcmd verify ~17s, then
 * ~50s of world load). Two faults compounded:
 *   1. a fixed short wait, with "port not up yet" treated as failure;
 *   2. the customer-facing mapper (lib/power-state.ts) did not recognise the
 *      worker's "never answered" wording and fell through to "we couldn't reach
 *      the server", which read as a platform fault and invited repeat clicks.
 *
 * Rule now: a start is FAILED only when the game process is dead (crashed /
 * stopped / unhealthy) — never merely because the port is not bound yet while
 * the unit is active. Running-but-not-yet-listening ends the job DONE with an
 * honest "still starting" outcome; the dashboard badge shows "Starting".
 */
import type { GameControlSpec } from "./game-control";
import type { GameRuntimeState } from "./game-runtime";

/** Default readiness window for families with no documented slow start. */
export const GAME_POWER_DEFAULT_WINDOW_MS = 30_000;

/**
 * Families whose boot is documented (in this repo) as slower than the default
 * but that do not carry `powerStartTimeoutMs` on their control spec.
 * projectzomboid: worker/game-config.ts already waits 180s for it.
 */
const FAMILY_WINDOW_MS: Record<string, number> = {
  projectzomboid: 180_000,
};

/** Readiness window for a family: its spec override, else the table, else the default. */
export function startWindowMs(spec: Pick<GameControlSpec, "family" | "powerStartTimeoutMs">): number {
  return spec.powerStartTimeoutMs ?? FAMILY_WINDOW_MS[spec.family] ?? GAME_POWER_DEFAULT_WINDOW_MS;
}

/** Runtime states that mean the game process is not alive. */
const DEAD_STATES: ReadonlySet<GameRuntimeState> = new Set(["crashed", "game_stopped", "not_responding"]);

export type StartOutcome =
  | { kind: "up" }
  | { kind: "starting"; note: string }
  | { kind: "dead"; reason: string };

function deadReason(state: GameRuntimeState): string {
  if (state === "crashed") return "the game process crashed or is restart-looping";
  if (state === "game_stopped") return "the game process exited";
  return "the game process is running but reports unhealthy";
}

/**
 * Settle the outcome after the port wait.
 *  - portOk                      -> up
 *  - aborted (process dead early) -> dead, with the real reason
 *  - window ended: probe the guest; dead states fail, anything else is "starting"
 *    (an unreadable guest is also "starting": we do not claim a failure we did not observe).
 */
export function judgeStart(input: {
  portOk: boolean;
  aborted?: boolean;
  abortReason?: string;
  runtimeState: GameRuntimeState | null;
}): StartOutcome {
  if (input.portOk) return { kind: "up" };
  if (input.aborted) return { kind: "dead", reason: input.abortReason ?? "the game process is not running" };
  const s = input.runtimeState;
  if (s && DEAD_STATES.has(s)) return { kind: "dead", reason: deadReason(s) };
  return {
    kind: "starting",
    note: "The game service is running and still loading; the port was not answering yet when our check window ended.",
  };
}

export type PowerStartDeps = {
  /** Wait for the port; `shouldAbort` lets a dead process end the wait early. */
  waitPort: (
    windowMs: number,
    shouldAbort: (attempt: number) => Promise<string | null>
  ) => Promise<{ ok: boolean; error?: string; aborted?: boolean; target: string | null } | null>;
  /** Fresh guest probe -> runtime state (null = could not tell). */
  probeState: () => Promise<GameRuntimeState | null>;
};

/** Probe every Nth failed attempt, and require two consecutive dead verdicts (a restart blips). */
const PROBE_EVERY = 3;

/**
 * Run the post-start check. Returns null when the family has no checkable
 * port (nothing to judge), else the outcome.
 */
export async function runPowerStartCheck(
  spec: Pick<GameControlSpec, "family" | "powerStartTimeoutMs">,
  deps: PowerStartDeps
): Promise<{ outcome: StartOutcome; target: string | null; detail: string } | null> {
  let deadStreak = 0;
  let abortReason: string | undefined;
  const shouldAbort = async (attempt: number): Promise<string | null> => {
    if (attempt % PROBE_EVERY !== 0) return null;
    const st = await deps.probeState();
    if (st && DEAD_STATES.has(st)) {
      deadStreak++;
      if (deadStreak >= 2) {
        abortReason = deadReason(st);
        return abortReason;
      }
    } else deadStreak = 0;
    return null;
  };
  const r = await deps.waitPort(startWindowMs(spec), shouldAbort);
  if (!r) return null;
  const state = r.ok || r.aborted ? null : await deps.probeState();
  const outcome = judgeStart({ portOk: r.ok, aborted: r.aborted, abortReason, runtimeState: state });
  return { outcome, target: r.target, detail: r.error ?? "" };
}

/**
 * Should a new start/restart be refused because the game is already coming up?
 * Stops repeat clicks stacking restarts on a slow-booting game. Only a FRESH
 * "starting" reading inside the start grace blocks; anything stale does not.
 */
export function startingBlocksRestart(
  row: { state: string | null; probedAt: Date | string | null; startedAt?: Date | string | null } | null,
  now: Date,
  opts: { freshMs?: number; graceMs?: number } = {}
): boolean {
  if (!row || row.state !== "starting" || !row.probedAt) return false;
  const fresh = now.getTime() - new Date(row.probedAt).getTime() < (opts.freshMs ?? 120_000);
  if (!fresh) return false;
  if (!row.startedAt) return true;
  return now.getTime() - new Date(row.startedAt).getTime() < (opts.graceMs ?? 6 * 60_000);
}
