import assert from "node:assert/strict";
import { runPowerStartCheck, startWindowMs, startingBlocksRestart, judgeStart } from "../lib/game-power-start.ts";
import { powerFailureMessage } from "../lib/power-state.ts";
import { controlSpec } from "../lib/game-control.ts";
import type { GameRuntimeState } from "../lib/game-runtime.ts";

/**
 * Valheim "terraheim" 2026-10-02: a restart whose port bound ~70s after start
 * was marked FAILED. Fakes only: no SSH, no clock.
 */

/** A fake port wait that "binds" at `bindAtMs` of simulated time, 3s ticks, honouring shouldAbort. */
function fakeWait(bindAtMs: number) {
  return async (windowMs: number, shouldAbort: (n: number) => Promise<string | null>) => {
    const attempts = Math.floor(windowMs / 3000) + 1;
    for (let i = 0; i < attempts; i++) {
      if (i * 3000 >= bindAtMs) return { ok: true, target: "1.2.3.4:2456" };
      const why = await shouldAbort(i + 1);
      if (why) return { ok: false, error: why, aborted: true, target: "1.2.3.4:2456" };
    }
    return { ok: false, error: "ECONNREFUSED", target: "1.2.3.4:2456" };
  };
}

test("valheim has a window longer than its ~75s boot", () => {
  assert.ok(startWindowMs(controlSpec("valheim")!) >= 180_000);
  assert.equal(startWindowMs({ family: "factorio", powerStartTimeoutMs: undefined } as never), 30_000);
});

test("slow-start family that binds at 70s succeeds without FAILED", async () => {
  const r = await runPowerStartCheck(controlSpec("valheim")!, {
    waitPort: fakeWait(70_000),
    probeState: async () => "starting",
  });
  assert.equal(r!.outcome.kind, "up");
});

test("window ends with the process alive and still loading -> starting, not dead", async () => {
  const r = await runPowerStartCheck({ family: "factorio" }, { waitPort: fakeWait(10 ** 9), probeState: async () => "starting" });
  assert.equal(r!.outcome.kind, "starting");
});

test("unreadable guest at window end is 'starting', never a claimed failure", async () => {
  const r = await runPowerStartCheck({ family: "factorio" }, { waitPort: fakeWait(10 ** 9), probeState: async () => null });
  assert.equal(r!.outcome.kind, "starting");
});

test("crash-looping process fails fast with a real reason", async () => {
  let probes = 0;
  const r = await runPowerStartCheck(controlSpec("valheim")!, {
    waitPort: fakeWait(10 ** 9),
    probeState: async () => (probes++, "crashed" as GameRuntimeState),
  });
  assert.equal(r!.outcome.kind, "dead");
  assert.match((r!.outcome as { reason: string }).reason, /crashed/);
  assert.ok(probes <= 6, "aborted well before the 180s window");
});

test("a single transient crashed blip does not abort", async () => {
  const seq: GameRuntimeState[] = ["crashed", "starting", "starting", "starting"];
  let i = 0;
  const r = await runPowerStartCheck(controlSpec("valheim")!, { waitPort: fakeWait(70_000), probeState: async () => seq[Math.min(i++, 3)] });
  assert.equal(r!.outcome.kind, "up");
});

test("dead process after the window also fails", () => {
  assert.equal(judgeStart({ portOk: false, runtimeState: "game_stopped" }).kind, "dead");
  assert.equal(judgeStart({ portOk: false, runtimeState: "starting" }).kind, "starting");
});

test("no port to check -> nothing to judge", async () => {
  assert.equal(await runPowerStartCheck({ family: "factorio" }, { waitPort: async () => null, probeState: async () => null }), null);
});

test("errors carry no secrets and map to a customer message", async () => {
  const r = await runPowerStartCheck(controlSpec("valheim")!, { waitPort: fakeWait(10 ** 9), probeState: async () => "crashed" });
  const reason = (r!.outcome as { reason: string }).reason;
  assert.doesNotMatch(reason, /password|token|secret/i);
  const err = `game power: restart failed, game process not running (${reason}) port 2456/udp`;
  assert.match(powerFailureMessage("game", "restart", err), /isn't staying up/);
  // legacy wording that used to fall through to "couldn't reach the server"
  const legacy = "game power: restart reported active but port 2456/udp never answered on 1.2.3.4:2456: ECONNREFUSED";
  assert.doesNotMatch(powerFailureMessage("game", "restart", legacy), /couldn't reach/);
});

test("repeat clicks are refused only while a fresh 'starting' reading is inside the grace", () => {
  const now = new Date("2026-10-02T06:00:00Z");
  const ago = (s: number) => new Date(now.getTime() - s * 1000);
  assert.equal(startingBlocksRestart({ state: "starting", probedAt: ago(20), startedAt: ago(40) }, now), true);
  assert.equal(startingBlocksRestart({ state: "starting", probedAt: ago(600), startedAt: ago(640) }, now), false);
  assert.equal(startingBlocksRestart({ state: "starting", probedAt: ago(20), startedAt: ago(900) }, now), false);
  assert.equal(startingBlocksRestart({ state: "online", probedAt: ago(20), startedAt: ago(40) }, now), false);
  assert.equal(startingBlocksRestart(null, now), false);
});
